node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { createFeed } from './src/index.mjs';

const feed = createFeed();
const input = { nested: { value: 1 } };
const published = feed.publishBatch('a', [{ type: 'created', payload: input }]);
input.nested.value = 2;
published[0].payload.nested.value = 3;
assert.equal(feed.history('a')[0].payload.nested.value, 1);

const first = [], second = [], otherTenant = [];
feed.subscribe('a', 0, record => { first.push(record); record.payload.nested.value = 4; });
feed.subscribe('a', 0, record => second.push(record));
feed.subscribe('b', 0, record => otherTenant.push(record));
feed.publishBatch('a', [{ type: 'updated', payload: { nested: { value: 5 } } }]);
assert.equal(first.at(-1).payload.nested.value, 4);
assert.equal(second.at(-1).payload.nested.value, 5);
assert.equal(otherTenant.length, 0);

const before = feed.history('a').map(record => record.sequence);
assert.throws(() => feed.publishBatch('a', [
  { type: 'valid', payload: {} },
  { type: 'invalid', payload: { notCloneable() {} } },
]));
assert.deepEqual(feed.history('a').map(record => record.sequence), before);
assert.equal(feed.publishBatch('a', [{ type: 'retry', payload: {} }])[0].sequence, 3);
console.log('contract smoke checks passed');
